def readServersEnv() {
    def result = [:]
    def envFile = rootProject.file('servers.env')
    if (envFile.exists()) {
        envFile.eachLine { line ->
            def trimmed = line.trim()
            if (trimmed && !trimmed.startsWith('#') && trimmed.contains('=')) {
                def idx = trimmed.indexOf('=')
                result[trimmed.substring(0, idx).trim()] = trimmed.substring(idx + 1).trim()
            }
        }
    }
    def propsFile = rootProject.file('gradle.properties')
    if (propsFile.exists()) {
        def props = new Properties()
        propsFile.withInputStream { props.load(it) }
        result.each { k, v -> if (!props.containsKey(k)) { } }
        for (def key : result.keySet()) {
            if (props.containsKey(key)) {
                result[key] = props.getProperty(key)
            }
        }
    }
    return result
}
